code.source:
#include <iostream>
#include <string>
using namespace std;

void show(const string& text) {
    cout << "Text: " << text << endl;
}

int main() {
    string line = "Goa has many beaches";
    show(line);
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

bool longer(const string& a, const string& b) {
    return a.size() > b.size();
}

int main() {
    string x = "Panjim";
    string y = "Mapusa";
    cout << boolalpha << longer(x, y) << endl;
    cout << longer("Margao", "Goa") << endl;
    return 0;
}

